use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Truncates a key string for display purposes"] # [doc = ""] # [doc = " If the key length is 20 characters or less, returns it unchanged."] # [doc = " Otherwise, shows the first 13 characters and last 4 characters with \"...\" in"] # [doc = " between."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `key` - The key string to truncate"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A truncated version of the key for safe display"] pub fn truncate_key (key : & str) -> String { let char_count = key . chars () . count () ; if char_count <= 20 { key . to_string () } else { let prefix : String = key . chars () . take (13) . collect () ; let suffix : String = key . chars () . skip (char_count - 4) . collect () ; format ! ("{prefix}...{suffix}") } }